INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p309224-fin399', 'stk-user4543', 'FIN 399', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته :\n\nإخوتي الأفاضل طلاب جامعة الملك فهد للبترول والمعادن أبارك لكم حلول شهر رمضان المبارك\n\nجعلنا اللهم من صوامه وقوامه يا أرحم الراحمين …\n\nإخوتي الأفاضل أتيتكم طالبة النصح والإرشاد من باب ماخاب من إستشار فأختكم كانت ضحية\n\nمخرجات التعلم وضيق الخيارات حينما تخرجت من المرحلة الثانوية رغم حصولي على نسبة\n\nعالية ولله الحمد ولكن كما قيل تجري الرياح بما لاتشتهي السفن فبعد عامين من دراسة\n\nالمتطلبات في الجامعة لم يكن لي خيار سوى دراسة تخصص اللغة العربية الذي لم أختره ولم\n\nأشعر بيوم أنه يعبر عني تجرعت المرارة وأنا أجوب أنحاء المملكة بحثا عن وظيفية لم أستثني\n\nالقطاع العام والخاص وحتى الدراسات العليا تقدمت عليها ولكن دون جدوى وأستمر الوضع\n\nلعامين تلقيت خلاله عدد من الدورات التدريبية في مجالات متعددة بالحاسب الالي وإدارة الأعمال\n\nكنت أمني النفس بالعمل في شركة عريقة كأرامكو السعودية حتى ولولفترة التدريب الصيفي\n\nوكذلك المصارف وعلى الرغم من تخرجي بمرتبة شرف ولكني لم أنل ذات الفرصة التي نالتها\n\nزميلاتي على الرغم من تدني معدلاتهم ولكن كونهن خريجات تخصصات مطلوبة بسوق العمل\n\nولكون رحمة الله واسعة فقد قبلت ببرنامج الإبتعاث وأصبت بهلوسة وقلق لم أستطع حيالها\n\nإختيار تخصص دقيق جراء ذهابي المتكرر بشكل يومي للتقديم على مدى عامين واختلاف\n\nالتوجهات وصاحب كل سلعة يروج لبضاعته قائلا هذا التخصص أفضل من ذاك وهلم جرا فأخترت\n\nماجستير حاسب الي خبط عشواء لمجرد الذهاب للولايات المتحدة الأمريكية والان لي 10 أشهر\n\nوحتى الان لازال القلق مسيطر علي والخيارات متعددة للغاية لا أود تكرار ماحصل معي بالأمس\n\nفقررت أن أتم 4أشهر إضافية باللغة حتى أصل إلى تخصص معين وقد قمت بتغيير تخصصي من\n\nالجامعة بتخصص Mba- Finance وأنا الان أتوجه لديكم بالسؤال والمشورة في أفضل التخصصات\n\nالمطلوبة بسوق العمل من ناحية الرواتب وكثرة الطلب وهل حينما أحصل على درجة الماجستير\n\nفي تخصص ما سيتم النظر إلى تخصصي السابق في البكالوريوس , علما بأني أفكر في العمل\n\nهناك حتى أحصل على خبرة في ذات المجال الذي سأعمل به أنتظر رأيكم وتفاعلكم كما\n\nعودتمونا …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/66122/1", "user": "user4543", "ts": 1221013537000, "tid": 66122, "pn": 1}}', 1221013537000, 1794826860, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
